    cells = {(r, c) for r in range(barh, hh) for c in range(ww) if int(A[r, c]) == objc}
    objs = []
    pool = set(cells)
    while pool:
        s = pool.pop()
        comp = {s}
        stack = [s]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if (nr, nc) in pool:
                    pool.discard((nr, nc))
                    comp.add((nr, nc))
                    stack.append((nr, nc))
        objs.append(comp)
    if not objs:
        return finish()

    # ---- 3. match every object to its notch (exact cover of the notch cells) ----
    def build_candidates(restrict):
        out = []
        for obj in objs:
            rs = [r for r, _ in obj]
            cs = [c for _, c in obj]
            r0, c0 = min(rs), min(cs)
            oh = max(rs) - r0 + 1
            ow = max(cs) - c0 + 1
            norm = {(r - r0, c - c0) for r, c in obj}
            cands = []
            for mk in range(1, min(oh, barh - 1) + 1):
                marker = {(r, c) for r, c in norm if r < mk}
                if not marker:
                    continue
